// One inbound customer message from the chat widget or the email-to-webhook
// bridge. Nothing downstream is allowed to trust a field this node did not set.
//
// The widget signs nothing useful, so the gate here is a shared secret compared
// in constant time. Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto on the instance.
const crypto = require('crypto');

const secret = $env.SUPPORT_WEBHOOK_SECRET;
if (!secret) throw new Error('SUPPORT_WEBHOOK_SECRET is not set on this n8n instance');

const out = [];

for (const item of $input.all()) {
  const headers = item.json.headers || {};
  const presented = String(headers['x-support-secret'] || '');

  const a = Buffer.from(presented.padEnd(secret.length, '\0').slice(0, secret.length), 'utf8');
  const b = Buffer.from(secret, 'utf8');
  if (presented.length !== secret.length || !crypto.timingSafeEqual(a, b)) {
    throw new Error('Inbound support webhook rejected: bad or missing x-support-secret');
  }

  const body = item.json.body || {};

  const email = String(body.email || body.from || '').trim().toLowerCase();
  const message = String(body.message || body.text || '').trim();

  if (!email.includes('@')) throw new Error('Inbound message has no usable customer email');
  if (!message) throw new Error('Inbound message is empty');

  // Customers write "#1042", "order 1042", "my order no. 1042". Take the first
  // 3+ digit run as a hint only - it is re-checked against the real order later.
  const hint = message.match(/#?\b(\d{3,})\b/);

  const receivedAt = body.received_at || new Date().toISOString();

  // Stable key for the decision log, so a retried delivery cannot double-log.
  //
  // The widget does not always send an id. Falling back to the empty string
  // gave every such message the key ":", and the ON CONFLICT DO NOTHING in the
  // decision log then silently dropped every message after the first - the
  // reply still went out, but nothing was recorded. With no upstream id, hash
  // the message instead: a replay of the same body still collides, two
  // different customers never do.
  const upstreamId = String(body.message_id || body.conversation_id || '');
  const decisionKey = upstreamId
    ? upstreamId + ':' + receivedAt
    : 'sha256:' + crypto.createHash('sha256').update([email, message, receivedAt].join('\n')).digest('hex');

  out.push({
    json: {
      decision_key: decisionKey,
      conversation_id: String(body.conversation_id || body.message_id || 'conv-' + Date.now()),
      channel: String(body.channel || 'web_widget'),
      customer_email: email,
      customer_name: String(body.name || '').trim() || null,
      message,
      order_reference_hint: hint ? hint[1] : null,
      received_at: receivedAt,
    },
  });
}

return out;

