      "name": "support_intent",
      "strict": true,
      "schema": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "intent",
          "confidence",
          "order_reference",
          "touches_money",
          "summary",
          "language"
        ],
        "properties": {
          "intent": {
            "type": "string",
            "enum": [
              "order_status",
              "refund",
              "product_question",
