// One webhook delivery is one customer message, so .first() is the whole batch.
// The model is asked for strict JSON. It is still parsed defensively: a model
// that returns prose, a truncated object, or an intent outside the enum must
// end up in the human queue, never in an auto-reply.
const inbound = $('Normalise Inbound').first().json;
const response = $input.first().json;

const ALLOWED = ['order_status', 'refund', 'product_question', 'complaint', 'other'];

let parsed = null;
let parseError = null;

try {
  const content = response?.choices?.[0]?.message?.content;
  if (typeof content !== 'string') throw new Error('no message content in the LLM response');
  parsed = JSON.parse(content);
} catch (e) {
  parseError = e.message;
}

const refusal = response?.choices?.[0]?.message?.refusal || null;
if (refusal) parseError = 'model refused: ' + refusal;

const intent = ALLOWED.includes(parsed?.intent) ? parsed.intent : 'other';

let confidence = Number(parsed?.confidence);
if (!Number.isFinite(confidence)) confidence = 0;
confidence = Math.min(1, Math.max(0, confidence));
if (parseError || !ALLOWED.includes(parsed?.intent)) confidence = 0;

// The model's own money flag is trusted only in the direction that adds
// caution. A keyword sweep can raise it; nothing can lower it.
const MONEY_WORDS = /refund|chargeback|charged|charge|money back|cancel|invoice|discount|coupon|double.?bill|overcharg/i;
const touches_money = Boolean(parsed?.touches_money) || MONEY_WORDS.test(inbound.message) ||
  intent === 'refund';

return [
  {
    json: {
      ...inbound,
      intent,
      confidence,
      touches_money,
      summary: String(parsed?.summary || '').slice(0, 400) || inbound.message.slice(0, 400),
      language: String(parsed?.language || 'en').slice(0, 16),
      order_reference: parsed?.order_reference ? String(parsed.order_reference) : inbound.order_reference_hint,
      classifier_model: response?.model || $env.LLM_MODEL || null,
      classifier_error: parseError,
    },
  },
];

// WooCommerce order search is a substring search across a lot of fields, so a
// result is not proof of ownership. Nothing about an order is disclosed until
// the billing email on that order matches the address the message came from.
const ctx = $('Parse Classification').first().json;

// Full Response is on, so this is always exactly one item: the list, however
// short, plus the status code.
const orders = ($input.first().json.body || []).filter((o) => o && o.id);

const wanted = ctx.order_reference ? String(ctx.order_reference) : null;

const owned = orders.filter(
  (o) => String(o?.billing?.email || '').trim().toLowerCase() === ctx.customer_email,
);

let order = null;
if (wanted) order = owned.find((o) => String(o.id) === wanted || String(o.number) === wanted) || null;
if (!order && !wanted) order = owned[0] || null;

if (!order) {
  // No auto-reply. Either the reference belongs to somebody else's order or the
  // customer wrote from a different address than they ordered with - both are
  // things a human should look at, and neither is a safe guess.
  return [
    {
      json: {
        ...ctx,
        confidence: 0,
        gate_reason: wanted
          ? 'order ' + wanted + ' is not on file for ' + ctx.customer_email
          : 'no orders on file for ' + ctx.customer_email,
        reply_text: null,
        reply_source: 'order_lookup',
      },
    },
  ];
}

const money = (v) => (order.currency_symbol || order.currency || '') + Number(v || 0).toFixed(2);
const lines = (order.line_items || [])
  .map((li) => '  - ' + li.quantity + ' x ' + li.name + ' (' + money(li.total) + ')')
  .join('\n');

const tracking = (order.meta_data || []).find((m) => /tracking/i.test(m.key || ''));
const shipped = ['completed'].includes(order.status);

const text = [
  'Hi ' + ((order.billing && order.billing.first_name) || 'there') + ',',
  '',
  'Order #' + order.number + ' placed on ' + String(order.date_created).slice(0, 10) +
    ' is currently *' + String(order.status).replace(/-/g, ' ') + '*.',
  '',
  lines,
  '',
  'Order total: ' + money(order.total),
  tracking ? 'Tracking: ' + tracking.value : (shipped ? 'Tracking will follow by email.' : ''),
  '',
  'Anything else I can check for you?',
]
  .filter(Boolean)
  .join('\n');

return [
  {
    json: {
      ...ctx,
      // The reply is assembled from fields read out of WooCommerce a second
      // ago, so the answer cannot drift from the store's own state.
      reply_text: text,
      reply_source: 'woocommerce_order',
      order_id: order.id,
      order_number: order.number,
      order_status: order.status,
      order_total: order.total,
      gate_reason: null,
    },
  },
];

// Deliberately not a vector store. Twenty-odd store policies fit in memory, the
// retrieval is deterministic, there is no embedding bill and no index to keep in
// sync with the store. Swap this node for a Vector Store node when the corpus
// outgrows a page - the contract downstream (passages + retrieval_score) is the
// same either way.
const ctx = $('Parse Classification').first().json;

const FAQ = [
  { id: 'shipping-times', title: 'Shipping times', text: 'UK orders ship within 1 working day and arrive in 2-3 working days. EU orders take 5-8 working days. Rest of world 10-14 working days. Orders placed after 2pm Friday ship the next Monday.' },
  { id: 'shipping-cost', title: 'Shipping cost', text: 'UK delivery is 3.95 GBP and free over 40 GBP. EU delivery is 9.95 GBP. Tracked shipping is included on every order over 40 GBP.' },
  { id: 'returns', title: 'Returns policy', text: 'Unopened items can be returned within 30 days for a full refund. Opened coffee and tea cannot be returned for hygiene reasons unless the item is faulty. Return postage is paid by the customer unless the item arrived damaged.' },
  { id: 'freshness', title: 'Roast date and freshness', text: 'Every bag is roasted to order and shows a roast date, not a best before date. Beans are at their best between 7 and 35 days after roasting. Store them sealed, at room temperature, away from light.' },
  { id: 'grind', title: 'Grind options', text: 'Choose whole bean, filter, cafetiere or espresso grind at checkout. Whole bean keeps its flavour longest. We cannot change the grind once an order has been packed.' },
  { id: 'subscriptions', title: 'Subscriptions', text: 'Subscriptions renew every 2, 4 or 6 weeks and can be paused, skipped or cancelled from the account area at any time before the renewal date. Subscribers get 10 percent off and free UK shipping.' },
  { id: 'decaf', title: 'Decaf process', text: 'Our decaf is Swiss Water processed, so it is chemical free and retains 99.9 percent caffeine free status.' },
  { id: 'origins', title: 'Origins and sourcing', text: 'We buy from named farms and cooperatives in Ethiopia, Colombia, Brazil, Rwanda and Guatemala, and publish the price paid to the producer on every product page.' },
  { id: 'wholesale', title: 'Wholesale', text: 'Cafes and offices can open a wholesale account for orders over 5kg a month, with invoice terms and next day delivery.' },
  { id: 'gift', title: 'Gift orders and notes', text: 'Add a gift note at checkout and we will include a handwritten card. Prices are never shown on the packing slip for gift orders.' },
  { id: 'allergens', title: 'Allergens', text: 'Coffee and tea are packed in a facility that also handles milk powder and nuts for our hot chocolate range.' },
  { id: 'payment', title: 'Payment methods', text: 'We accept all major cards, Apple Pay, Google Pay, PayPal and Klarna. Payment is taken when the order is placed.' },
];

const STOP = new Set('a an and are as at be but by do does for from how i in is it its my me of on or our so that the their them then there these this to us was we what when where which who why will with you your'.split(' '));

function tokens(s) {
  return String(s).toLowerCase().replace(/[^a-z0-9 ]/g, ' ').split(/\s+/).filter((t) => t.length > 2 && !STOP.has(t));
}

const qSet = new Set(tokens(ctx.message));

const indexed = FAQ.map((entry) => ({ ...entry, terms: new Set(tokens(entry.title + ' ' + entry.text)) }));
const vocabulary = new Set(indexed.flatMap((e) => [...e.terms]));

// Terms the corpus has never heard of are not evidence of a bad match - the
// store simply has no word for "EU" or for the customer's name. They are
// excluded from the denominator, but counted as a penalty, because a question
// that is mostly unknown vocabulary is a question this corpus cannot answer.
const known = [...qSet].filter((t) => vocabulary.has(t));
const familiarity = qSet.size ? known.length / qSet.size : 0;

const scored = indexed
  .map((entry) => {
    const overlap = known.filter((t) => entry.terms.has(t)).length;
    const coverage = known.length ? overlap / known.length : 0;
    return { ...entry, overlap, score: coverage * (0.5 + 0.5 * familiarity) };
  })
  .sort((a, b) => b.score - a.score);

// One matching word is a coincidence. Two is a match.
const top = scored.filter((s) => s.overlap >= 2).slice(0, 2);
const retrievalScore = top.length ? top[0].score : 0;

// Two independent reasons to hand over: the classifier was unsure, or the store
// simply has no policy that answers this. min() means either one is enough.
const confidence = Math.min(ctx.confidence, retrievalScore >= 0.5 ? 0.95 : retrievalScore);

const text = top.length
  ? [
      'Hi ' + (ctx.customer_name || 'there') + ',',
      '',
      top.map((t) => t.text).join('\n\n'),
      '',
      'If that does not cover it, just reply here and one of us will pick it up.',
    ].join('\n')
  : null;

return [
  {
    json: {
      ...ctx,
      confidence,
      reply_text: text,
      reply_source: 'faq_keyword_retrieval',
      retrieval_score: Number(retrievalScore.toFixed(3)),
      retrieved_passages: top.map((t) => t.id),
      gate_reason: top.length ? null : 'no FAQ passage matched the question',
    },
  },
];

// Reached from the error output of every tool call in this workflow. A tool that
// is down must not turn into a confident-sounding guess, and must not turn into
// silence either - it becomes a human queue item with the failure attached.
const ctx = $('Normalise Inbound').first().json;
const failure = $input.first().json;

const error = failure?.error || failure;
const message = error?.message || error?.description || 'tool call failed with no message';

return [
  {
    json: {
      ...ctx,
      intent: $('Parse Classification').isExecuted ? $('Parse Classification').first().json.intent : 'other',
      confidence: 0,
      touches_money: $('Parse Classification').isExecuted
        ? $('Parse Classification').first().json.touches_money
        : true,
      reply_text: null,
      reply_source: 'tool_failure',
      gate_reason: 'tool call failed: ' + String(message).slice(0, 300),
    },
  },
];

// Everything the person picking this up needs, in the message itself: what was
// asked, what the agent thought, and exactly why it refused to answer.
const c = $input.first().json;

const reason = c.gate_reason
  || (c.touches_money ? 'touches money - policy is that a human answers' : null)
  || 'confidence ' + c.confidence + ' is below the threshold ' + ($env.SUPPORT_CONFIDENCE_THRESHOLD || '0.75');

return [
  {
    json: {
      ...c,
      review_reason: reason,
      slack_payload: {
        text: 'Support message needs a human: ' + c.customer_email,
        blocks: [
          { type: 'header', text: { type: 'plain_text', text: 'Support handover - ' + c.intent } },
          {
            type: 'section',
            fields: [
              { type: 'mrkdwn', text: '*Customer*\n' + c.customer_email },
              { type: 'mrkdwn', text: '*Intent*\n' + c.intent + ' (' + c.confidence + ')' },
              { type: 'mrkdwn', text: '*Touches money*\n' + (c.touches_money ? 'yes' : 'no') },
              { type: 'mrkdwn', text: '*Channel*\n' + c.channel },
            ],
          },
          { type: 'section', text: { type: 'mrkdwn', text: '*Message*\n' + String(c.message).slice(0, 2500) } },
          { type: 'context', elements: [{ type: 'mrkdwn', text: 'Held because: ' + reason }] },
        ],
      },
    },
  },
];

// One row per decision, whichever way the gate went. The auto branch records
// what was sent so a bad reply can be traced back to the classification that
// produced it.
const c = $('Confidence Gate').first().json;
const delivery = $input.first().json;

return [
  {
    json: {
      decision_key: c.decision_key,
      conversation_id: c.conversation_id,
      customer_email: c.customer_email,
      channel: c.channel,
      intent: c.intent,
      confidence: c.confidence,
      touches_money: c.touches_money,
      action: 'auto_replied',
      reply_source: c.reply_source,
      reply_text: c.reply_text,
      gate_reason: null,
      classifier_model: c.classifier_model || null,
      classifier_error: c.classifier_error || null,
      external_ref: delivery?.id || delivery?.message_id || null,
      execution_id: $execution.id,
    },
  },
];

const c = $('Build Handover Payload').first().json;
const delivery = $input.first().json;
const slackFailed = Boolean(delivery?.error);

return [
  {
    json: {
      decision_key: c.decision_key,
      conversation_id: c.conversation_id,
      customer_email: c.customer_email,
      channel: c.channel,
      intent: c.intent,
      confidence: c.confidence,
      touches_money: c.touches_money,
      action: 'human_review',
      reply_source: c.reply_source,
      reply_text: null,
      gate_reason: c.review_reason,
      classifier_model: c.classifier_model || null,
      classifier_error: c.classifier_error || null,
      // A Slack outage must not lose the handover: the row is written either
      // way and the queue table is the source of truth, not the Slack message.
      external_ref: slackFailed ? 'slack_delivery_failed' : 'slack_notified',
      execution_id: $execution.id,
    },
  },
];
